package com.lqq.supportflow.action.infrastructure.persistence;
import com.lqq.supportflow.action.domain.ActionExecutionPort; import java.time.Instant; import org.springframework.dao.DuplicateKeyException; import org.springframework.stereotype.Component;
@Component public class MyBatisActionExecutionAdapter implements ActionExecutionPort { private final ActionExecutionMapper mapper; public MyBatisActionExecutionAdapter(ActionExecutionMapper mapper){this.mapper=mapper;} public void executeOnce(Long tenantId,Long approvalId,String actionType){ActionExecutionEntity entity=new ActionExecutionEntity();entity.tenantId=tenantId;entity.approvalId=approvalId;entity.actionType=actionType;entity.status="EXECUTED";entity.executedAt=Instant.now();try{mapper.insert(entity);}catch(DuplicateKeyException ignored){}}}
